alter table public.profiles add column if not exists tc_email text;                -- this agent's assigned TC
alter table public.profiles add column if not exists licenses jsonb not null default '[]'::jsonb;  -- [{state, number, expiration}]
alter table public.profiles add column if not exists annual_cap numeric;           -- overrides the plan's cap
alter table public.profiles add column if not exists team_id text;
alter table public.profiles add column if not exists permissions jsonb not null default '{}'::jsonb;
alter table public.profiles add column if not exists alerts_sent jsonb not null default '[]'::jsonb;
create index if not exists profiles_brokerage_idx on public.profiles (brokerage_id);

-- Create a profile row whenever someone signs up
create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, email, full_name)
  values (new.id, new.email, coalesce(new.raw_user_meta_data->>'full_name', ''))
  on conflict (id) do nothing;
  return new;
end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- Helpers used by the security policies
create or replace function public.auth_email() returns text language sql stable as $$
  select lower(coalesce(auth.jwt()->>'email', ''))
$$;
create or replace function public.auth_brokerage_id() returns text
language sql stable security definer set search_path = public as $$
  select brokerage_id from public.profiles where id = auth.uid()
$$;
create or replace function public.auth_role() returns text
language sql stable security definer set search_path = public as $$
  select role from public.profiles where id = auth.uid()
$$;
create or replace function public.is_super_admin() returns boolean language sql stable as $$
  select coalesce(public.auth_role() = 'super_admin', false)
$$;
-- Legacy Base44 roles map onto the new ones: admin -> office_admin, user -> agent.
create or replace function public.normalize_role(r text) returns text language sql immutable as $$
  select case coalesce(r, 'agent') when 'admin' then 'office_admin' when 'user' then 'agent' when 'super_admin' then 'owner' else coalesce(r, 'agent') end
$$;
create or replace function public.is_brokerage_admin() returns boolean language sql stable as $$
  select coalesce(public.normalize_role(public.auth_role()) in ('owner', 'broker', 'office_admin'), false)
$$;

-- Roles and permissions. Generated by scripts/gen_permissions.py; edit that file.
-- Per-user overrides live in profiles.permissions ({"tx.all": true, ...}).

create or replace function public.perm_default(role text, key text) returns boolean language sql immutable as $$
  select case key
    when 'tx.create' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'tx.edit' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'tx.delete' then r in ('broker','office_admin','owner')
    when 'tx.cancel' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'tx.all' then r in ('broker','office_admin','owner')
    when 'tx.checklist_manage' then r in ('broker','office_admin','owner','tc')
    when 'tx.checklist_add' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'tx.checklist_remove' then r in ('broker','office_admin','owner','tc')
    when 'tx.close' then r in ('broker','office_admin','owner','tc')
    when 'tx.reopen' then r in ('broker','office_admin','owner')
    when 'tx.edit_emd' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'tx.view_commissions' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'tx.share' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'offers.access' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'offers.create' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'offers.edit' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'offers.delete' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'offers.all' then r in ('broker','office_admin','owner')
    when 'pipeline.individual' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'reports.personal' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'reports.company' then r in ('broker','office_admin','owner')
    when 'contacts.private_all' then r in ('broker','office_admin','owner')
    when 'activity.account' then r in ('broker','office_admin','owner')
    when 'activity.transaction' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'library.access' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'library.manage' then r in ('broker','office_admin','owner')
    when 'library.private_all' then r in ('broker','office_admin','owner')
    when 'docs.approve' then r in ('broker','office_admin','owner')
    when 'docs.approve2' then r in ('broker','owner')
    when 'docs.submit_tx' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'docs.submit_individual' then r in ('agent','broker','office_admin','owner','tc','team_leader')
    when 'settings.manage' then r in ('broker','owner')
    when 'accounting.access' then r in ('broker','office_admin','owner')
    when 'users.manage' then r in ('broker','office_admin','owner')
    else false end
  from (select public.normalize_role(role) as r) x
$$;

create or replace function public.has_perm(key text) returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(
    (select case when p.permissions ? key then (p.permissions ->> key)::boolean
                 else public.perm_default(p.role, key) end
       from public.profiles p where p.id = auth.uid()),
    false)
$$;

create or replace function public.auth_team_id() returns text
language sql stable security definer set search_path = public as $$
  select team_id from public.profiles where id = auth.uid()
$$;
create or replace function public.is_team_leader() returns boolean language sql stable as $$
  select coalesce(public.normalize_role(public.auth_role()) = 'team_leader', false)
$$;
-- Team leaders see their team members' deals.
create or replace function public.leads_agent(agent_email text) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_team_leader() and public.auth_team_id() is not null and exists (
    select 1 from public.profiles p where lower(p.email) = lower(agent_email) and p.team_id = public.auth_team_id())
$$;


create or replace function public.touch_updated_date() returns trigger language plpgsql as $$
begin new.updated_date = now(); return new; end $$;

-- Base44 filled these in automatically; keep doing that so records never go missing
-- from a brokerage because a screen forgot to send brokerage_id.
create or replace function public.fill_owner() returns trigger language plpgsql as $$
begin
  if new.created_by is null then new.created_by := nullif(public.auth_email(), ''); end if;
  if new.brokerage_id is null then new.brokerage_id := public.auth_brokerage_id(); end if;
  return new;
end $$;
create or replace function public.fill_creator() returns trigger language plpgsql as $$
begin
  if new.created_by is null then new.created_by := nullif(public.auth_email(), ''); end if;
  return new;
end $$;

alter table public.profiles enable row level security;
drop policy if exists profiles_read on public.profiles;
create policy profiles_read on public.profiles for select using (
  id = auth.uid() or brokerage_id = public.auth_brokerage_id() or public.is_super_admin());
drop policy if exists profiles_update_self on public.profiles;
create policy profiles_update_self on public.profiles for update using (id = auth.uid())
  with check (id = auth.uid()
    and role = public.auth_role()
    and brokerage_id is not distinct from public.auth_brokerage_id());
-- Joining a brokerage or changing roles goes through server routes (service role).
drop policy if exists profiles_admin on public.profiles;
create policy profiles_admin on public.profiles for update using (
  (public.is_brokerage_admin() and brokerage_id = public.auth_brokerage_id()) or public.is_super_admin())
  with check (public.is_super_admin() or (role <> 'super_admin' and brokerage_id = public.auth_brokerage_id()));
-- Agents can edit their own profile, but not the fields that decide pay, permissions or team.
create or replace function public.guard_profile_self_edit() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.is_brokerage_admin() then return new; end if;
  if new.role is distinct from old.role
     or new.brokerage_id is distinct from old.brokerage_id
     or new.duties is distinct from old.duties
     or new.commission_plan_id is distinct from old.commission_plan_id
     or new.team_lead_email is distinct from old.team_lead_email
     or new.sponsor_email is distinct from old.sponsor_email
     or new.cap_start_date is distinct from old.cap_start_date
     or new.start_date is distinct from old.start_date
     or new.suspended is distinct from old.suspended
     or new.permissions is distinct from old.permissions
     or new.annual_cap is distinct from old.annual_cap
     or new.team_id is distinct from old.team_id
     or new.tc_email is distinct from old.tc_email then
    raise exception 'Only an admin can change role, permissions, team, plan, cap, TC or sponsor fields';
  end if;
  return new;
end $$;
drop trigger if exists profiles_guard on public.profiles;
create trigger profiles_guard before update on public.profiles for each row execute function public.guard_profile_self_edit();
drop trigger if exists profiles_touch on public.profiles;
create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_date();

